def quantum_security(classical_bits, algo_type):
    if algo_type == 'symmetric' or algo_type == 'hash_preimage':
        return classical_bits / 2
    elif algo_type == 'hash_collision':
        return classical_bits / 3  # approx
    else:  # RSA, ECC – broken by Shor
        return 0

print(f"AES-128 quantum security: {quantum_security(128, 'symmetric')} bits")
print(f"RSA-2048 quantum security: {quantum_security(112, 'asymmetric')} bits")
